import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    static class Solver {
        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 11) {
                out.println("0");
                return;
            }
            ArrayList<Point> points = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                points.add(new Point(in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt()));
            }
            Set<Integer> good = new HashSet<>();
            for (int i = 0; i < n; i++) {
                boolean isGood = true;
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i == j || i == k || j == k) continue;
                        Point v1 = points.get(j).minus(points.get(i));
                        Point v2 = points.get(k).minus(points.get(i));
                        if (isAcute(v1, v2)) {
                            isGood = false;
                            break;
                        }
                    }
                    if (!isGood) break;
                }
                if (isGood) good.add(i + 1);
            }
            if (good.isEmpty()) {
                out.println("0");
            } else {
                out.println(good.size());
                for (int idx : good) out.println(idx);
            }
        }

        static boolean isAcute(Point a, Point b) {
            double dot = a.p * b.p + a.q * b.q + a.r * b.r + a.s * b.s + a.t * b.t;
            double ang = Math.toDegrees(Math.acos(dot / (a.mag() * b.mag())));
            return ang < 90;
        }
    }

    static class Point {
        int p, q, r, s, t;
        Point(int p, int q, int r, int s, int t) {
            this.p = p; this.q = q; this.r = r; this.s = s; this.t = t;
        }
        Point minus(Point o) {
            return new Point(p - o.p, q - o.q, r - o.r, s - o.s, t - o.t);
        }
        double mag() {
            return Math.sqrt(p*p + q*q + r*r + s*s + t*t);
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;
        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }
}
